def decode(logits, channels):
    if channels < 1:
        raise ValueError("need at least one channel")
    if len(logits) % channels:
        raise ValueError("logits length is not a multiple of the channel count")
    out = []
    for start in range(0, len(logits), channels):
        block = logits[start:start + channels]
        best = 0
        for index in range(1, channels):
            if block[index] > block[best]:
                best = index
        out.append(best)
    return out


def regressed(values, channels):
    if channels < 1:
        raise ValueError("need at least one channel")
    return [min(channels - 1, max(0, int(round(v)))) for v in values]


def diversity(samples):
    if not samples:
        raise ValueError("no samples")
    unique = {tuple(s) for s in samples}
    positions = len(samples[0])
    if any(len(s) != positions for s in samples):
        raise ValueError("samples differ in length")
    varying = 0
    for i in range(positions):
        if len({s[i] for s in samples}) > 1:
            varying += 1
    return {"unique": len(unique), "total": len(samples),
            "varying_positions": varying,
            "collapsed": len(unique) <= max(1, len(samples) // 10)}


def memorised(samples, corpus, distance):
    if not corpus:
        raise ValueError("empty corpus")
    copies = 0
    nearest = []
    for sample in samples:
        d = min(distance(sample, item) for item in corpus)
        nearest.append(d)
        if d == 0:
            copies += 1
    return {"copies": copies, "nearest": nearest,
            "mean_nearest": sum(nearest) / len(nearest)}
